import java.io.*;
import java.util.*;

public class fivedimpoints {
    static int n;
    static int[][] coord;
    static boolean[] bad;

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws IOException {
        FastReader in = new FastReader();
        n = in.nextInt();
        if (n > 11) {
            System.out.println(0);
            return;
        }
        coord = new int[n][5];
        bad = new boolean[n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 5; j++) {
                coord[i][j] = in.nextInt();
            }
        }
        int count = n;
        for (int i = 0; i < n; i++) {
            boolean found = false;
            for (int j = 0; j < n && !found; j++) {
                if (j == i) continue;
                for (int k = 0; k < n && !found; k++) {
                    if (k == i || k == j) continue;
                    long prod = 0;
                    for (int m = 0; m < 5; m++) {
                        long a = coord[j][m] - coord[i][m];
                        long b = coord[k][m] - coord[i][m];
                        prod += a * b;
                    }
                    if (prod > 0) {
                        found = true;
                        bad[i] = true;
                        count--;
                    }
                }
            }
        }
        System.out.println(count);
        for (int i = 0; i < n; i++) {
            if (!bad[i]) System.out.println(i + 1);
        }
    }
}
